const originalOverlay=$('originalOverlay');function updateOverlay(){if(!lastImage||!$('compareOriginal').checked){originalOverlay.style.display='none';return}originalOverlay.style.display='block';originalOverlay.width=canvas.width;originalOverlay.height=canvas.height;originalOverlay.style.width=canvas.style.width;originalOverlay.style.height=canvas.style.height;const c=originalOverlay.getContext('2d');c.clearRect(0,0,originalOverlay.width,originalOverlay.height);c.globalAlpha=.3;const iw=lastImage.naturalWidth,ih=lastImage.naturalHeight;let dx=0,dy=0,dw=originalOverlay.width,dh=originalOverlay.height;const mode=$('imageMode').value;if(mode==='contain'){const scale=Math.min(dw/iw,dh/ih);const width=iw*scale,height=ih*scale;dx=(dw-width)/2;dy=(dh-height)/2;dw=width;dh=height}else if(mode==='cover'){const scale=Math.max(dw/iw,dh/ih);const width=iw*scale,height=ih*scale;dx=(dw-width)/2;dy=(dh-height)/2;dw=width;dh=height}c.drawImage(lastImage,dx,dy,dw,dh)}
