function zipArchive(entries){const enc=new TextEncoder();const blocks=[],central=[];let offset=0;const u16=n=>[n&255,(n>>>8)&255],u32=n=>[n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255];const crc32=bytes=>{let v=0xffffffff;for(const byte of bytes){v^=byte;for(let j=0;j<8;j++)v=(v>>>1)^((v&1)?0xedb88320:0)}return (v^0xffffffff)>>>0};for(const entry of entries){const name=enc.encode(entry.name),data=entry.data,crc=crc32(data);const header=Uint8Array.from([...u32(0x04034b50),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0)]);blocks.push(header,name,data);const centralHeader=Uint8Array.from([...u32(0x02014b50),...u16(20),...u16(20),...u16(0),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset)]);central.push(centralHeader,name);offset+=header.length+name.length+data.length;}const centralSize=central.reduce((n,x)=>n+x.length,0),end=Uint8Array.from([...u32(0x06054b50),...u16(0),...u16(0),...u16(entries.length),...u16(entries.length),...u32(centralSize),...u32(offset),...u16(0)]);return new Blob([...blocks,...central,end],{type:'application/zip'})}
$('downloadBoards').onclick=async()=>{const bs=Number($('boardSize').value),entries=[];for(let yy=0;yy<h;yy+=bs)for(let xx=0;xx<w;xx+=bs){const bw=Math.min(bs,w-xx),bh=Math.min(bs,h-yy),s=28;const ca=document.createElement('canvas');ca.width=bw*s;ca.height=bh*s;const c=ca.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,ca.width,ca.height);for(let y=0;y<bh;y++)for(let x=0;x<bw;x++){const color=byCode.get(cells[(yy+y)*w+xx+x]);if(color){c.fillStyle=color.hex;c.fillRect(x*s,y*s,s,s)}c.strokeStyle='#ccc';c.strokeRect(x*s+.5,y*s+.5,s-1,s-1);if(color){c.fillStyle=(color.rgb[0]+color.rgb[1]+color.rgb[2])<365?'white':'#333';c.font='9px sans-serif';c.textAlign='center';c.fillText(color.code,x*s+s/2,y*s+s/2+3)}}const blob=await new Promise(r=>ca.toBlob(r,'image/png'));if(!blob)continue;entries.push({name:`board-${Math.floor(yy/bs)+1}-${Math.floor(xx/bs)+1}.png`,data:new Uint8Array(await blob.arrayBuffer())})}if(!entries.length)return;download(zipArchive(entries),safeName()+'-boards.zip');toast(v22('boardDone')+` (${entries.length})`)};
